CREATE TEMPORARY VIEW dws_search_volume_${grass_region_without_quote} AS
SELECT
    '__ALL__' AS address_state
    ,IF(local_hour IS NOT NULL, CAST(local_hour AS STRING), '__ALL__') AS local_hour
    ,'__ALL__' AS use_instant_filter_type
    ,'__ALL__' AS layout_type
