CREATE TEMPORARY VIEW dwd_instant_filter_click_imp_${grass_region_without_quote} AS
SELECT
    user_id
    ,local_hour
    ,ARRAY_DISTINCT(FILTER(
        TRANSFORM(search_filter_string, x -> FROM_JSON(x, 'STRUCT<filter_name:STRING,address_id:BIGINT>'))
        ,x -> LOWER(x.filter_name) IN ('instant_delivery', 'fast_delivery')
    )) AS search_filter
    ,operation
FROM
    srdi_mart.dwd_sr_data_warehouse_search
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND user_id > 0
    AND ((
        operation = 'click'
        AND original_operation = 'action_filter'
        AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill')  
        AND page_section IS NULL
        AND target_type IS NULL
    ) OR (
        page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
        AND page_section[0] = 'search_filter_shortcut_bar'
        AND target_type = 'filter_button'
        AND operation = 'impression'
    ))
    AND EXISTS(TRANSFORM(search_filter_string, x -> FROM_JSON(x, 'STRUCT<filter_name:STRING,address_id:BIGINT>'))
        ,x -> LOWER(x.filter_name) IN ('instant_delivery', 'fast_delivery')
    );

