CREATE TEMPORARY VIEW dws_click_imp_order_other_metrics_${grass_region_without_quote} AS
SELECT
    IF(GROUPING(address_state) = 1, '__ALL__', COALESCE(address_state, 'NULL')) AS address_state
    ,IF(GROUPING(local_hour) = 1, '__ALL__', CAST(local_hour AS STRING)) AS local_hour
    ,IF(GROUPING(use_instant_filter_type) = 1, '__ALL__', use_instant_filter_type) AS use_instant_filter_type
    ,IF(GROUPING(layout_type) = 1, '__ALL__', layout_type) AS layout_type
    ,IF(GROUPING(target_type) = 1, '__ALL__', target_type) AS card_type
    ,SUM(IF(operation = 'impression', operation_cnt, NULL)) AS imp_cnt
    ,SUM(IF(operation = 'impression' AND target_type = 'item', operation_cnt, NULL)) AS imp_item_cnt
    ,COUNT(DISTINCT IF(operation = 'impression', a.user_id, NULL)) AS imp_uu
    ,SUM(IF(operation = 'click', operation_cnt, NULL)) AS click_cnt
    ,COUNT(DISTINCT IF(operation = 'click', a.user_id, NULL)) AS click_uu
    ,SUM(IF(operation = 'order' AND operation_cnt > 0, operation_cnt, NULL)) AS order_cnt
    ,COUNT(DISTINCT IF(operation = 'order' AND operation_cnt > 0, a.user_id, NULL)) AS order_uu
    ,SUM(IF(operation = 'order' AND operation_cnt > 0, place_order_gmv, NULL)) AS gmv
    ,COUNT(DISTINCT IF(operation = 'impression' AND layout_type = '3', (a.user_id, device_id, keyword), NULL)) AS shop_search_volume
    ,SUM(IF(operation = 'impression' AND layout_type = '3' AND target_type = 'shop', has_empty_shop_layout_item, NULL)) AS empty_shop_imp_cnt
FROM
    dwd_click_imp_order_metrics_explode_${grass_region_without_quote} a
LEFT JOIN
    user_address_state_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
    AND a.search_filter_detail.address_id = b.address_id
GROUP BY
    CUBE(address_state, local_hour, use_instant_filter_type, layout_type, target_type);

--sql_divide_splitter--

