CREATE TEMPORARY VIEW dwd_ads_revenue_${grass_region_without_quote} AS
SELECT
    raw_request_id
    ,item_id
    ,SUM(expenditure_amt_usd) AS ads_rev
FROM
    mp_paidads.dwd_advertise_performance_di__reg_s0_live
WHERE
    grass_region = ${grass_region}
    AND grass_date = ${local_date}
    AND user_id > 0
    AND entrance = 1
    AND tz_type = 'local'
    AND expenditure_amt_usd IS NOT NULL
GROUP BY
    1,2;

