CREATE TEMPORARY VIEW dwm_ads_revenue_${grass_region_without_quote} AS
SELECT
-- Unlinkable ads_revenue rows need to be in NULL and __ALL__ categories
-- Becauses __ALL__ has been generated previously above, cannot grouping sets directly
-- Still need to put ads_rev of NULL into __ALL__ as well
    COALESCE(address_state, 'NULL') AS address_state
    ,COALESCE(local_hour, 'NULL') AS local_hour
    ,COALESCE(use_instant_filter_type, 'NULL') AS use_instant_filter_type
    ,COALESCE(layout_type, 'NULL') AS layout_type
    ,SUM(ads_rev) AS ads_rev
FROM
    dwd_ads_revenue_${grass_region_without_quote} a
LEFT JOIN
    dwm_ads_revenue_link_${grass_region_without_quote} b
ON
    a.raw_request_id = b.request_id
    AND a.item_id = b.item_id
GROUP BY
    1,2,3,4;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_ads_revenue_${grass_region_without_quote} AS
SELECT
-- Adding unlinked ads_revenue into __ALL__ category as well
    address_state
    ,local_hour
    ,use_instant_filter_type
    ,layout_type
    ,'__ALL__' AS card_type
    ,ads_rev
FROM
    dwm_ads_revenue_${grass_region_without_quote}
WHERE NOT (
    address_state = '__ALL__'
    AND local_hour = '__ALL__'
    AND use_instant_filter_type = '__ALL__'
    AND layout_type = '__ALL__'
)
UNION ALL
SELECT
     '__ALL__' AS address_state
    ,'__ALL__' AS local_hour
    ,'__ALL__' AS use_instant_filter_type
    ,'__ALL__' AS layout_type
    ,'__ALL__' AS card_type
    ,SUM(ads_rev) AS ads_rev
FROM
    dwm_ads_revenue_${grass_region_without_quote}
WHERE 
    (
        address_state = '__ALL__'
        AND local_hour = '__ALL__'
        AND use_instant_filter_type = '__ALL__'
        AND layout_type = '__ALL__'
    ) OR (
        address_state = 'NULL'
        AND local_hour = 'NULL'
        AND use_instant_filter_type = 'NULL'
        AND layout_type = 'NULL'
    )
GROUP BY
    1,2,3,4,5;

