SELECT
    IF(GROUPING(local_hour) = 1, '__ALL__', CAST(local_hour AS STRING)) AS local_hour
    ,SUM(CASE WHEN (
            (reporting_business_line = 'Search' AND reporting_module = 'Global Search')
            OR (source1_reporting_business_line = 'Search' AND source1_reporting_module = 'Global Search')
            OR (source2_reporting_business_line = 'Search' AND source2_reporting_module = 'Global Search')
        ) THEN operation_cnt ELSE NULL
    END) AS global_search_order_cnt
    ,SUM(CASE WHEN (
            (reporting_business_line = 'Search' AND reporting_module = 'Global Search')
            OR (source1_reporting_business_line = 'Search' AND source1_reporting_module = 'Global Search')
            OR (source2_reporting_business_line = 'Search' AND source2_reporting_module = 'Global Search')
        ) THEN place_order_gmv ELSE NULL
    END) AS global_search_gmv
    ,SUM(operation_cnt) AS platform_order_cnt
    ,SUM(place_order_gmv) AS platform_gmv
FROM
    srdi_mart.dwd_sr_data_warehouse_platform
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND operation = 'order'
GROUP BY
    CUBE(local_hour);

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_main_metrics_${grass_region_without_quote} AS
SELECT
-- Each view can have metrics for dims in which other metrics are absent
    COALESCE(a.address_state, b.address_state, c.address_state, d.address_state) AS address_state
    ,COALESCE(a.local_hour, b.local_hour, c.local_hour, d.local_hour) AS local_hour
    ,COALESCE(a.use_instant_filter_type, b.use_instant_filter_type, c.use_instant_filter_type, d.use_instant_filter_type) AS use_instant_filter_type
    ,COALESCE(a.layout_type, b.layout_type, c.layout_type, d.layout_type) AS layout_type
    ,COALESCE(a.card_type, b.card_type, c.card_type, d.card_type) AS card_type
    ,direct_search_success_volume
    ,broad_search_success_volume
    ,imp_cnt
    ,imp_item_cnt
    ,imp_uu
    ,click_cnt
    ,click_uu
    ,order_cnt
    ,order_uu
    ,gmv
    ,avg_edt
    ,ads_rev
    ,shop_search_volume
    ,empty_shop_imp_cnt
FROM
    dws_click_imp_order_other_metrics_${grass_region_without_quote} a
FULL JOIN
    dws_direct_broad_search_volume_${grass_region_without_quote} b
ON
    a.address_state = b.address_state
    AND a.local_hour = b.local_hour
    AND a.use_instant_filter_type = b.use_instant_filter_type
    AND a.layout_type = b.layout_type
    AND a.card_type = b.card_type
FULL JOIN
    dws_avg_edt_${grass_region_without_quote} c
ON
    COALESCE(a.address_state, b.address_state) = c.address_state
    AND COALESCE(a.local_hour, b.local_hour) = c.local_hour
    AND COALESCE(a.use_instant_filter_type, b.use_instant_filter_type) = c.use_instant_filter_type
    AND COALESCE(a.layout_type, b.layout_type) = c.layout_type
    AND COALESCE(a.card_type, b.card_type) = c.card_type
FULL JOIN
    dws_ads_revenue_${grass_region_without_quote} d
ON
    COALESCE(a.address_state, b.address_state, c.address_state) = d.address_state
    AND COALESCE(a.local_hour, b.local_hour, c.local_hour) = d.local_hour
    AND COALESCE(a.use_instant_filter_type, b.use_instant_filter_type, c.use_instant_filter_type) = d.use_instant_filter_type
    AND COALESCE(a.layout_type, b.layout_type, c.layout_type) = d.layout_type
    AND COALESCE(a.card_type, b.card_type, c.card_type) = d.card_type;

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_state_srp_layout_instant_filter_metrics_1d
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT
    COALESCE(a.address_state, b.address_state, c.address_state, d.address_state) AS address_state
    ,COALESCE(a.local_hour, b.local_hour, c.local_hour, d.local_hour) AS local_hour
    ,COALESCE(a.use_instant_filter_type, b.use_instant_filter_type, c.use_instant_filter_type, d.use_instant_filter_type) AS use_instant_filter_type
    ,COALESCE(a.layout_type, b.layout_type, c.layout_type, d.layout_type) AS layout_type

    ,search_uu
    ,search_volume
    ,instant_filter_uu
    ,instant_filter_using_cnt
    ,no_results_cnt
    ,no_results_volume
    ,instant_filter_no_results_cnt
    ,instant_filter_no_results_volume

    ,direct_search_success_volume
    ,broad_search_success_volume
    ,imp_cnt
    ,imp_item_cnt
    ,imp_uu
    ,click_cnt
    ,click_uu
    ,order_cnt
    ,order_uu
    ,gmv
    ,avg_edt
    ,ads_rev

    ,COALESCE(a.card_type, b.card_type, c.card_type, d.card_type) AS card_type
    ,instant_filter_imp_uu
    ,instant_filter_imp_cnt
    ,shop_search_volume
    ,empty_shop_imp_cnt
    ,shop_item_fill_rate
    ,global_search_order_cnt
    ,global_search_gmv
    ,platform_order_cnt
    ,platform_gmv
FROM
    dws_main_metrics_${grass_region_without_quote} a
FULL JOIN
    dws_no_results_metrics_${grass_region_without_quote} b
ON
    a.address_state = b.address_state
    AND a.local_hour = b.local_hour
    AND a.use_instant_filter_type = b.use_instant_filter_type
    AND a.layout_type = b.layout_type
    AND a.card_type = b.card_type
FULL JOIN
    dws_instant_filter_click_imp_${grass_region_without_quote} c
ON
    COALESCE(a.address_state, b.address_state) = c.address_state
    AND COALESCE(a.local_hour, b.local_hour) = c.local_hour
    AND COALESCE(a.use_instant_filter_type, b.use_instant_filter_type) = c.use_instant_filter_type
    AND COALESCE(a.layout_type, b.layout_type) = c.layout_type
    AND COALESCE(a.card_type, b.card_type) = c.card_type
FULL JOIN
    dws_search_volume_${grass_region_without_quote} d
ON
    COALESCE(a.address_state, b.address_state, c.address_state) = d.address_state
    AND COALESCE(a.local_hour, b.local_hour, c.local_hour) = d.local_hour
    AND COALESCE(a.use_instant_filter_type, b.use_instant_filter_type, c.use_instant_filter_type) = d.use_instant_filter_type
    AND COALESCE(a.layout_type, b.layout_type, c.layout_type) = d.layout_type
    AND COALESCE(a.card_type, b.card_type, c.card_type) = d.card_type
LEFT JOIN
    global_search_and_platform_metrics_${grass_region_without_quote} e
ON
    COALESCE(a.address_state, b.address_state, c.address_state, d.address_state) = '__ALL__'
    AND COALESCE(a.local_hour, b.local_hour, c.local_hour, d.local_hour) = e.local_hour
    AND COALESCE(a.use_instant_filter_type, b.use_instant_filter_type, c.use_instant_filter_type, d.use_instant_filter_type) = '__ALL__'
    AND COALESCE(a.layout_type, b.layout_type, c.layout_type, d.layout_type) = '__ALL__'
    AND COALESCE(a.card_type, b.card_type, c.card_type, d.card_type) = '__ALL__'
LEFT JOIN
    dws_shop_item_fill_rate_${grass_region_without_quote} f
ON
    COALESCE(a.address_state, b.address_state, c.address_state, d.address_state) = f.address_state
    AND COALESCE(a.local_hour, b.local_hour, c.local_hour, d.local_hour) = f.local_hour
    AND COALESCE(a.use_instant_filter_type, b.use_instant_filter_type, c.use_instant_filter_type, d.use_instant_filter_type) = f.use_instant_filter_type
    AND COALESCE(a.layout_type, b.layout_type, c.layout_type, d.layout_type) = '3'
    AND COALESCE(a.card_type, b.card_type, c.card_type, d.card_type) = '__ALL__';
